function Status(props){

  const topMessage=""
  const paragraph=""
  if(props.status==="won")
  {
    topMessage="You Win!"
    paragraph="Well done!🎉"
  }
  else if(props.status==="lost")
  {
    topMessage="Game Over!"
    paragraph="You lose"
  }

  return(
    <div className={props.status}>
        <h2>{topMessage}</h2>
        <p></p>
    </div>
  )
}

export default Status
